import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { loadTokenFiles, resolveTokens } from './lib/tokens.mjs';

const scriptDirectory = path.dirname(fileURLToPath(import.meta.url));
const repositoryDirectory = path.resolve(scriptDirectory, '..');
const outputDirectory = path.join(repositoryDirectory, 'design-system/tokens/build');
const header = [
  '/* GENERATED by scripts/build-tokens.mjs from design-system/tokens/*.json - do not edit */',
  '',
].join('\n');

function cssValue(token) {
  if (typeof token.$value === 'string' && /^\{[^{}]+\}$/.test(token.$value)) {
    const reference = token.$value.slice(1, -1).replaceAll('.', '-');
    return `var(--ds-${reference})`;
  }
  if (token.$type === 'fontFamily') {
    return token.$value.map((font) => (/\s/.test(font) ? `"${font}"` : font)).join(', ');
  }
  return String(token.$value);
}

function primitiveVariable(token) {
  if (token.path.startsWith('font.')) {
    return `--ds-font-${token.path.split('.')[1]}`;
  }
  return `--ds-${token.path.replaceAll('.', '-')}`;
}

function isPrimitive(token) {
  return ['color.', 'font.', 'spacing.', 'radius.']
    .some((prefix) => token.path.startsWith(prefix));
}

function isSemantic(token) {
  return ['layout.', 'component.', 'focus.']
    .some((prefix) => token.path.startsWith(prefix));
}

function typographyDeclarations(typography) {
  const declarations = [];
  for (const token of typography) {
    const role = token.path;
    const value = token.$value;
    const familyReference = value.fontFamily.slice(1, -1).replaceAll('.', '-');
    const family = `var(--ds-${familyReference})`;
    let size = value.fontSize;
    const fluid = token.$extensions?.ds?.fluid;

    if (fluid) {
      const minimum = Number.parseFloat(fluid.min);
      const maximum = Number.parseFloat(value.fontSize);
      const delta = maximum - minimum;
      // 920px is the responsive viewport range: 1280px minus 360px.
      size = `clamp(${minimum}px, calc(${minimum}px + ${delta} * `
        + `((100vw - 360px) / 920)), ${maximum}px)`;
    }

    const fields = [
      ['family', family],
      ['size', size],
      ['weight', value.fontWeight],
      ['leading', value.lineHeight],
      ['tracking', value.letterSpacing],
    ];
    for (const [name, fieldValue] of fields) {
      declarations.push(`  --ds-type-${role}-${name}: ${fieldValue};`);
    }
  }
  return declarations;
}

function typeClasses(typography) {
  const lines = [];
  for (const token of typography) {
    const role = token.path;
    lines.push(
      `.ds-type-${role} {`,
      `  font-family: var(--ds-type-${role}-family);`,
      `  font-size: var(--ds-type-${role}-size);`,
      `  font-weight: var(--ds-type-${role}-weight);`,
      `  line-height: var(--ds-type-${role}-leading);`,
      `  letter-spacing: var(--ds-type-${role}-tracking);`,
      '}',
      '',
    );
  }
  return lines;
}

function buildTokensCss(tokens) {
  const primitives = tokens.filter(isPrimitive);
  const semantic = tokens.filter(isSemantic);
  const typography = tokens.filter((token) => token.$type === 'typography');
  const lines = [
    header,
    ':root {',
    ...primitives.map((token) => (
      `  ${primitiveVariable(token)}: ${cssValue(token)};`
    )),
    ...semantic.map((token) => {
      const name = token.path.split('.').slice(1).join('-');
      return `  --ds-${name}: ${cssValue(token)};`;
    }),
    ...typographyDeclarations(typography),
    '}',
    '',
    ...typeClasses(typography),
  ];
  return lines.join('\n');
}

function themeTokens(tokens, name) {
  return tokens.filter((token) => token.file === `themes/${name}.tokens.json`);
}

function themeBlock(tokens, name, selector) {
  const declarations = themeTokens(tokens, name).map((token) => {
    const themePath = token.path.replace(/^themes\.(?:light|dark)\./, '');
    const variable = themePath.replaceAll('.', '-');
    return `  --ds-${variable}: ${cssValue(token)};`;
  });
  return [
    `${selector} {`,
    `  color-scheme: ${name};`,
    ...declarations,
    '}',
  ].join('\n');
}

function buildThemesCss(tokens) {
  const automaticDark = themeBlock(tokens, 'dark', '[data-ds-theme="auto"]')
    .split('\n')
    .map((line) => `  ${line}`)
    .join('\n');
  const lines = [
    header,
    themeBlock(tokens, 'light', ':root'),
    '',
    themeBlock(tokens, 'light', '[data-ds-theme="light"]'),
    '',
    themeBlock(tokens, 'dark', '[data-ds-theme="dark"]'),
    '',
    '@media (prefers-color-scheme: dark) {',
    automaticDark,
    '}',
    '',
  ];
  return lines.join('\n');
}

function outputFiles(tokens) {
  return new Map([
    [
      'design-system/tokens/build/tokens.css',
      buildTokensCss(tokens),
    ],
    [
      'design-system/tokens/build/themes.css',
      buildThemesCss(tokens),
    ],
  ]);
}

function writeOrCheck(files, checkOnly) {
  let differs = false;
  for (const [relativePath, contents] of files) {
    const absolutePath = path.join(repositoryDirectory, relativePath);
    if (checkOnly) {
      if (!fs.existsSync(absolutePath) || fs.readFileSync(absolutePath, 'utf8') !== contents) {
        console.error(`${relativePath} differs`);
        differs = true;
      }
      continue;
    }
    fs.mkdirSync(outputDirectory, { recursive: true });
    fs.writeFileSync(absolutePath, contents);
  }
  if (differs) process.exitCode = 1;
}

function main() {
  const { tokens } = resolveTokens(loadTokenFiles());
  const checkOnly = process.argv.includes('--check');
  writeOrCheck(outputFiles(tokens), checkOnly);
}

try {
  main();
} catch (error) {
  const message = error instanceof Error ? error.message : String(error);
  console.error(`build-tokens: ${message.replaceAll('\n', ' ')}`);
  process.exitCode = 1;
}
